WITH state(kind, obj, cid, name, type, nn, dflt, pk) AS (SELECT 'object', name, -1, type, tbl_name, 0, NULL, 0 FROM sqlite_schema WHERE substr(name,1,7)<>'sqlite_' UNION ALL SELECT 'column', 't1', cid, name, type, "notnull", dflt_value, pk FROM pragma_table_info('t1') UNION ALL SELECT 'column', 't2', cid, name, type, "notnull", dflt_value, pk FROM pragma_table_info('t2') UNION ALL SELECT 'column', 't3', cid, name, type, "notnull", dflt_value, pk FROM pragma_table_info('t3')) SELECT kind, obj, cid, name, type, nn, dflt, pk FROM state ORDER BY kind, obj, cid;